<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>اطلاعات شرکت | حسابداری</title><style>body{font-family:Tahoma,sans-serif;background:#07111f;color:#e9f3fb;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}.panel{background:#0a1b2b;border:1px solid #1b354b;border-radius:18px;padding:24px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.head a{color:#6ee7d0;text-decoration:none}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:12px;color:#91a7ba}.field input,.field textarea{background:#0d2235;border:1px solid #29455d;color:#e9f3fb;border-radius:9px;padding:11px;font:inherit}.field textarea{min-height:90px}.actions{margin-top:20px}.btn{background:#6ee7d0;color:#06202a;border:0;border-radius:9px;padding:11px 18px;cursor:pointer;font-weight:700}.error{color:#ff9b9b;font-size:11px}.success{color:#6ee7d0;margin-bottom:15px;font-size:12px}@media(max-width:700px){.grid{grid-template-columns:1fr}.field.full{grid-column:auto}}</style></head><body><div class="wrap"><div class="head"><h1>اطلاعات شرکت / مجموعه</h1><a href="{{ route('dashboard') }}">← داشبورد</a></div><div class="panel">@if(session('success'))<div class="success">{{ session('success') }}</div>@endif @if($errors->any())<div class="error">@foreach($errors->all() as $error)<div>{{ $error }}</div>@endforeach</div><br>@endif<form method="POST" action="{{ route('company.update') }}" enctype="multipart/form-data">@csrf @method('PUT')<div class="grid">@foreach([['name','نام','text'],['commercial_name','نام تجاری','text'],['entity_type','نوع مجموعه','text'],['national_id','شناسه ملی','text'],['registration_number','شماره ثبت','text'],['economic_code','کد اقتصادی','text'],['phone','تلفن','text'],['mobile','موبایل','text'],['email','ایمیل','email'],['website','وب‌سای